<template>
  <main class="page reminder-settings-page">
    <header class="topbar"><button type="button" class="icon-button" aria-label="返回" @click="router.back()"><AppIcon name="arrow-left" /></button><h1>活动与出票提醒</h1><span class="header-spacer"></span></header>
    <div class="container reminder-settings">
      <section class="reminder-intro"><span><AppIcon name="bell" size="24" /></span><div><h2>重要消息，及时知道</h2><p>出票成功、退款审核结果与订阅活动开售时，页面右上角会显示提醒。</p></div></section>
      <section class="card sound-settings"><h2>提示音设置</h2><label class="setting-row"><div><b>出票成功提示音</b><small>电子票生成后播放一次短提示音</small></div><input type="checkbox" role="switch" :checked="store.settings.issuedSound" @change="setSound('issuedSound', $event.target.checked)" /></label><label class="setting-row"><div><b>活动开售提示音</b><small>仅提醒你单独订阅的收藏活动</small></div><input type="checkbox" role="switch" :checked="store.settings.openingSound" @change="setSound('openingSound', $event.target.checked)" /></label><button class="sound-preview" type="button" @click="preview"><AppIcon name="bell" size="16" /> 试听提示音</button><p v-if="audioMessage" class="settings-note" role="status">{{ audioMessage }}</p><p class="settings-note">提示音默认关闭。网页需保持打开，浏览器允许播放声音后才能响起；文字提醒会正常显示。</p></section>
      <section class="card subscriptions"><div class="section-title"><h2>我的开售提醒</h2><RouterLink to="/favorites">去收藏订阅 <AppIcon name="chevron-right" size="14" /></RouterLink></div><p v-if="!activeSubscriptions.length" class="empty-note">暂无开售订阅。在收藏页为即将开售的活动开启提醒。</p><div v-for="subscription in activeSubscriptions" :key="subscription.id" class="subscription-row"><span><b>{{ subscription.title }}</b><small>正在关注开售状态</small></span><button type="button" @click="store.unsubscribe(subscription.id)">取消订阅</button></div></section>
      <section class="reminder-history"><div class="section-title"><h2>提醒记录</h2><span>最近 {{ store.history.length }} 条</span></div><p v-if="!store.history.length" class="card empty-note">暂无提醒。出票、退款审核有结果或订阅活动开售后，记录会显示在这里。</p><RouterLink v-for="item in store.history" :key="item.key" :to="item.to" class="card history-card"><span class="history-icon"><AppIcon :name="item.kind === 'issued' ? 'ticket' : 'bell'" size="19" /></span><div><b>{{ item.title }}</b><p>{{ item.message }}</p><small>{{ formatTime(item.createdAt) }}</small></div><AppIcon name="chevron-right" size="16" /></RouterLink></section>
    </div>
  </main>
</template>
<script setup>
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import { useRemindersStore } from '../../stores/reminders'
import { unlockReminderSound, playReminderSound } from '../../utils/reminderSound'
import AppIcon from '../../components/AppIcon.vue'
const router = useRouter(), store = useRemindersStore(), audioMessage = ref('')
const activeSubscriptions = computed(() => Object.values(store.subscriptions).filter(item => !item.delivered))
async function setSound(kind, enabled) { store.setSound(kind, enabled); if (enabled) await unlockReminderSound() }
async function preview() { const enabled = await unlockReminderSound(); audioMessage.value = enabled && playReminderSound() ? '已播放试听提示音' : '当前浏览器暂不支持播放，请检查声音权限。' }
function formatTime(value) { return new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Shanghai', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).format(value) }
</script>
