-size:11px;color:var(--muted)}.empty-note{padding:18px 12px;margin:0;font-size:12px;line-height:1.7;color:var(--muted);text-align:center}.subscription-row{display:flex;align-items:center;gap:10px;justify-content:space-between;padding:13px 0;border-top:1px solid var(--line)}.subscription-row>span{display:flex;flex-direction:column;gap:5px;min-width:0}.subscription-row b{font-size:13px;overflow-wrap:anywhere}.subscription-row button{flex:none;border:0;background:#edf2ff;color:var(--primary);border-radius:9px;padding:7px 10px;font-size:11px}.history-card{display:flex;align-items:flex-start;gap:10px;padding:15px;margin-bottom:10px;color:var(--text)}.history-icon{display:grid;place-items:center;width:34px;height:34px;flex:none;border-radius:10px;background:#edf3ff;color:var(--primary)}.history-card>div{flex:1;min-width:0}.history-card b{font-size:13px}.history-card p{font-size:12px;color:var(--muted);line-height:1.5;margin:5px 0;overflow-wrap:anywhere}.history-card small{font-size:10px;color:#8593a8}.history-card>.app-icon{margin-top:8px;color:var(--muted)}
